// revolve: a vase: a fit spline through (10, 0), (14, 10), (9, 25), (11, 35) closed by lines to the axis, revolved, shelled 1.2 open at its top
export function c001(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skFitSpline(profile, "spline1", { "points" : [vector(10, 0) * millimeter, vector(14, 10) * millimeter, vector(9, 25) * millimeter, vector(11, 35) * millimeter] });
    skLineSegment(profile, "l1", { "start" : vector(11, 35) * millimeter, "end" : vector(0, 35) * millimeter });
    skLineSegment(profile, "l2", { "start" : vector(0, 35) * millimeter, "end" : vector(0, 0) * millimeter });
    skLineSegment(profile, "l3", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skSolve(profile);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(-100, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    shell(context, id + "shell1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(0, 0, 35) * millimeter), "thickness" : 1.2 * millimeter });
}

